/**
 * Blender's two windows on the host kept for a visitor's files
 * (blendHandback.ts says why there are two, and why here).
 *
 * Both are this host's page opened as a window of its own, by another page.
 * That page is whoever opened the window and is trusted with nothing:
 *
 *  - The converting window takes one file, once, from the window that
 *    opened it and from no other, reads it as a stranger's, and notes the
 *    origin it came from. All a stranger's page gains by handing it a file
 *    is that file's world, back.
 *  - The window that gives the world back posts it to the window that opened
 *    it, addressed to the origin noted and to no other: the browser delivers
 *    it only if that is who opened the window. To anyone else it is a
 *    window that says one word and closes.
 *
 * The file and the world wait in this host's own cache meanwhile, which only
 * windows of this host see. They are forgotten when the world is taken, when
 * the next file arrives, and when a finished world has waited longer than
 * `HANDBACK_FOR_MS`.
 *
 * Once it is isolated the converting window can tell nobody anything. So it
 * writes how far it has got into its note as it goes, and again every few
 * seconds while it works. The second window reads that, and answers with
 * one word of five: the world itself, still converting, failed, stopped
 * (nothing written for a while: closed, or stuck), or nothing kept. Asking
 * early changes nothing that is kept.
 */
import { MAX_NOTE_ERRORS, blendWindowMode, handbackAnswer, handbackNote, isWebOrigin, readHandbackNote, type BlendProgress, type HandbackNote } from './blendHandback';
import { CONVERTER_WINDOW_CSS } from './blendStages';
import { classifyImport } from './importFiles';
import { importHandoff, importSignal, readImportModels, type HandoffFile, type ImportSignal } from './importHandoff';
import { showStage, type ImportDeps, type StageAction } from './importMode';
import { isIsolationRequest, isolatedUrl } from './isolation';
import { stashPendingImport, takeOpenedWorld, takePendingImport, type PendingStore } from './pendingImport';
import { IMPORT_PREFIX } from './worldInMemory';

/** This host's cache, as these windows use it. */
export interface BlendStore extends PendingStore {
  clear?(): Promise<void>;
}

/** The store and the folder its addresses are under. */
export interface Kept {
  store: BlendStore;
  scopeUrl: string;
}

const noteUrl = (scopeUrl: string): string => new URL(`${IMPORT_PREFIX}pending/handback.json`, scopeUrl).href;

async function readNote(kept: Kept, now: number): Promise<HandbackNote | null> {
  const raw = await kept.store.get(noteUrl(kept.scopeUrl));
  return raw === null ? null : readHandbackNote(new TextDecoder().decode(raw), now);
}

const writeNote = (kept: Kept, note: HandbackNote): Promise<void> => kept.store.put(noteUrl(kept.scopeUrl), new TextEncoder().encode(handbackNote(note)), 'application/json');

/** The clock the note is kept on: the time in ms, and a call every so often with a way to stop it. */
export interface ProgressClock {
  now(): number;
  every(ms: number, run: () => void): () => void;
}

/** How often the converting window writes its note again while nothing changes, in ms. */
const BEAT_EVERY_MS = 5_000;
/** How long one write of the note may take before it is given up and the next one goes, in ms. */
export const WRITE_GIVE_UP_MS = 10_000;

export interface Progress {
  /** The work is at `stage` now. Written at once. After `ready` or `failed` nothing more is written. */
  set(stage: BlendProgress, more?: { percent?: number; why?: string }): void;
  /** A line Blender said. Kept, the last one and a count, and written with the next beat, not on its own. */
  line(text: string): void;
  /** Something that went wrong around the work. Written at once; the first few are kept. */
  error(text: string): void;
  /** Resolves when everything set so far has been written, or could not be. */
  settled(): Promise<void>;
}

/**
 * Keeps the converting window's note: who the world is for (`origin`, null
 * while it still waits for the file), since when (`at`), each stage as it
 * is set, what Blender said last, and what went wrong. It is written again
 * every few seconds by a plain timer, so that a window that has gone quiet
 * can be told from one at work, and a window at work whose Blender has gone
 * quiet from both.
 *
 * One write goes at a time, of the note as it stands when it starts: what
 * changes meanwhile is written once, after it. A write that fails is said
 * in the next one, and a write that has not finished after
 * `WRITE_GIVE_UP_MS` is given up, said, and the next one goes, so nothing
 * stuck in the store can stop the beat. The note is an account of the work
 * and never part of it.
 */
export function keepProgress(kept: Kept, origin: string | null, at: number, clock: ProgressClock): Progress {
  let note: HandbackNote = { origin, at, stage: origin === null ? 'waiting' : 'kept', beat: clock.now() };
  let last: string | undefined;
  let lines = 0;
  const errors: string[] = [];
  let over = false;
  /** The write going now: when it started, and a number that tells it from one given up. */
  let going: { since: number; id: number } | null = null;
  let writes = 0;
  let again = false;
  let idle: Array<() => void> = [];
  const noteError = (text: string): void => {
    if (errors.length < MAX_NOTE_ERRORS) errors.push(text);
  };
  const finished = (id: number): void => {
    if (going?.id !== id) return;
    going = null;
    if (again) write();
    else {
      for (const resolve of idle) resolve();
      idle = [];
    }
  };
  const write = (): void => {
    if (going !== null) {
      again = true;
      return;
    }
    again = false;
    const id = ++writes;
    going = { since: clock.now(), id };
    const writing: HandbackNote = { ...note, beat: clock.now(), ...(last !== undefined ? { last, lines } : {}), ...(errors.length > 0 ? { errors: [...errors] } : {}) };
    let put: Promise<void>;
    try {
      put = writeNote(kept, writing);
    } catch (err) {
      put = Promise.reject(err);
    }
    put.then(
      () => finished(id),
      (err: unknown) => {
        noteError(`the note could not be written: ${err instanceof Error ? err.message : String(err)}`);
        finished(id);
      },
    );
  };
  const beat = (): void => {
    if (going !== null && clock.now() - going.since >= WRITE_GIVE_UP_MS) {
      noteError(`a write of the note did not finish in ${Math.round((clock.now() - going.since) / 1000)} s`);
      going = null;
    }
    write();
  };
  let stopBeating: (() => void) | null = clock.every(BEAT_EVERY_MS, beat);
  return {
    set(stage, more = {}) {
      if (over) return;
      // Every line Blender says comes here as "converting" again: the same stage is not a new write.
      if (stage === note.stage && more.percent === note.percent && more.why === note.why) return;
      over = stage === 'ready' || stage === 'failed';
      // A world is kept an hour from when it was ready, not from when its file arrived.
      note = { origin, at: stage === 'ready' ? clock.now() : at, stage, beat: clock.now(), ...(more.percent !== undefined ? { percent: more.percent } : {}), ...(more.why !== undefined ? { why: more.why } : {}) };
      if (over) {
        stopBeating?.();
        stopBeating = null;
      }
      write();
    },
    line(text) {
      last = text;
      lines += 1;
    },
    error(text) {
      if (over) return;
      noteError(text);
      write();
    },
    settled: () => (going === null ? Promise.resolve() : new Promise<void>((resolve) => idle.push(resolve))),
  };
}

/** Where the watchdog writes, beside the note: its own file, so it never writes over the window's. */
export const aliveUrl = (scopeUrl: string): string => new URL(`${IMPORT_PREFIX}pending/alive.json`, scopeUrl).href;
/** How often the watchdog writes, in ms. */
const ALIVE_EVERY_MS = 5_000;

/**
 * The text of a worker that writes `{ alive: <time> }` to `aliveUrl` every
 * few seconds. It has a thread of its own, so it goes on while the page's
 * main thread is stuck, and it stops when the page is gone: with the note's
 * beat, the two tell a stuck window from a gone one. Its only input is the
 * scope, written in as a string.
 */
export function watchdogSource(scopeUrl: string): string {
  const url = JSON.stringify(aliveUrl(scopeUrl));
  return (
    `const beat = () => caches.open('webverse-import').then((c) => c.put(${url}, new Response(JSON.stringify({ alive: Date.now() }), ` +
    `{ headers: { 'content-type': 'application/json', 'cache-control': 'no-store' } }))).catch(() => undefined);` +
    `beat(); setInterval(beat, ${ALIVE_EVERY_MS});`
  );
}

/** Starts the watchdog; a browser that will not start it is said in the note and the work goes on. */
function startWatchdog(win: Window, scopeUrl: string, note: (line: string) => void): void {
  try {
    const here = win as unknown as { Blob: typeof Blob; Worker: typeof Worker; URL: typeof URL };
    const source = new here.Blob([watchdogSource(scopeUrl)], { type: 'text/javascript' });
    new here.Worker(here.URL.createObjectURL(source));
  } catch (err) {
    note(`the watchdog could not start: ${told(err)}`);
  }
}

/** One line of what went wrong, from whatever was thrown or said. */
const told = (what: unknown): string => (what instanceof Error ? `${what.name}: ${what.message}` : String(what));

/**
 * What the converting window can see going wrong around Blender, told to
 * `note` one line at a time: its own errors and promises let fall, each
 * worker it starts failing or unable to read a message, a file of its own
 * host answered with an error, and the browser freezing the window. Nobody
 * sees this window, so this is how anyone learns what happened in it.
 * Returns the function that stops watching.
 */
export function watchForTrouble(win: Window, note: (line: string) => void): () => void {
  const onError = (event: ErrorEvent): void => {
    const where = event.filename ? ` (${event.filename.slice(event.filename.lastIndexOf('/') + 1)}:${event.lineno ?? 0})` : '';
    note(`${event.message || told(event.error)}${where}`);
  };
  const onRejection = (event: PromiseRejectionEvent): void => note(`a promise let fall: ${told(event.reason)}`);
  const onFreeze = (): void => note('the browser froze this window');
  // A navigation, a reload or a close ends the work as surely as a crash, and says so only here.
  const onLeaving = (): void => note('the window is about to leave this page');
  const onLeft = (): void => note('the window left this page');
  win.addEventListener('error', onError);
  win.addEventListener('unhandledrejection', onRejection);
  win.addEventListener('freeze', onFreeze);
  win.addEventListener('beforeunload', onLeaving);
  win.addEventListener('pagehide', onLeft);
  // The runtime starts its workers with the window's own Worker: each one started from here is watched too.
  const scope = win as unknown as { Worker: typeof Worker };
  const Native = scope.Worker;
  if (typeof Native === 'function') {
    scope.Worker = class extends Native {
      constructor(url: string | URL, options?: WorkerOptions) {
        super(url, options);
        const name = String(url).slice(String(url).lastIndexOf('/') + 1);
        this.addEventListener('error', (event: ErrorEvent) => note(`worker ${name} failed: ${event.message || 'it could not start'}`));
        this.addEventListener('messageerror', () => note(`worker ${name} sent a message the window could not read`));
      }
    };
  }
  // A file of this host that was answered with an error: the runtime's files and workers are all fetched here.
  let observer: PerformanceObserver | null = null;
  const Observer = (win as unknown as { PerformanceObserver?: typeof PerformanceObserver }).PerformanceObserver;
  if (typeof Observer === 'function') {
    try {
      observer = new Observer((list) => {
        for (const entry of list.getEntries() as Array<PerformanceEntry & { responseStatus?: number }>) {
          const status = entry.responseStatus ?? 0;
          if (status < 400) continue;
          try {
            const url = new URL(entry.name);
            // No config served is the usual case for a deployment that names no meeting place, not a fault.
            const noConfig = status === 404 && url.pathname.endsWith('/webverse.config.json');
            if (url.origin === win.location.origin && !noConfig) note(`${url.pathname} was answered ${status}`);
          } catch {
            // Not an address: nothing to say of it.
          }
        }
      });
      observer.observe({ type: 'resource', buffered: true });
    } catch {
      observer = null;
    }
  }
  return () => {
    win.removeEventListener('error', onError);
    win.removeEventListener('unhandledrejection', onRejection);
    win.removeEventListener('freeze', onFreeze);
    win.removeEventListener('beforeunload', onLeaving);
    win.removeEventListener('pagehide', onLeft);
    if (typeof Native === 'function') scope.Worker = Native;
    observer?.disconnect();
  };
}

/** The window that opened this one, as far as this one may use it: something to post to. */
interface Opener {
  postMessage(message: unknown, targetOrigin: string, transfer?: Transferable[]): void;
}

type Heard = (event: { source: unknown; origin: string; data: unknown }) => void;

/** The slice of `window` the converting window needs while it waits for its file. */
export interface AwaitingWindow {
  opener: unknown;
  addEventListener(type: 'message', listener: Heard): void;
  removeEventListener(type: 'message', listener: Heard): void;
}

/**
 * How waiting for the file ended: it is `kept`, and the window can go on;
 * `nobody` opened this window, so nobody will hand it one; what came was
 * `refused` as not a Blender file, or as from a page with no origin to give
 * the world back to; or keeping it `failed`.
 */
export type AwaitOutcome = 'kept' | 'nobody' | 'refused' | 'failed';

/**
 * Tells the window that opened this one that it is waiting, and takes the
 * first file that window hands it. No other window is heard, and nothing
 * after the first file. Returns the function that stops waiting.
 */
export function awaitBlendFile(win: AwaitingWindow, kept: () => Promise<Kept>, now: () => number, then: (outcome: AwaitOutcome) => void): () => void {
  const opener = (win.opener ?? null) as Opener | null;
  if (opener === null) {
    then('nobody');
    return () => undefined;
  }
  const onMessage: Heard = (event) => {
    if (event.source !== opener) return;
    const models = readImportModels(event.data);
    if (models === null) return;
    win.removeEventListener('message', onMessage);
    const picked = classifyImport(models);
    // The world goes back to this origin and no other, so one that is no origin at all is no one to convert for.
    if (picked.kind !== 'blend' || !isWebOrigin(event.origin)) {
      then('refused');
      return;
    }
    void (async () => {
      const place = await kept();
      // Whatever an earlier file left is not this visitor's concern any more.
      await place.store.clear?.();
      await stashPendingImport(place.store, place.scopeUrl, picked.model, picked.sidecars);
      await writeNote(place, { origin: event.origin, at: now(), stage: 'kept', beat: now() });
    })().then(
      () => then('kept'),
      () => then('failed'),
    );
  };
  win.addEventListener('message', onMessage);
  try {
    // The word carries nothing, so it may go to whoever opened this window.
    opener.postMessage(importSignal('waiting'), '*');
  } catch {
    // The window that opened this one is gone: nobody hands it a file, and its card says to choose it again.
  }
  return () => win.removeEventListener('message', onMessage);
}

/** What asking for the world came to: it was `sent`, or one of the four words said in its place. */
export type HandBack = 'sent' | Exclude<ImportSignal, 'waiting'>;

/**
 * Answers the window that opened this one, which is asking for the world.
 * If the world is ready and that window is on the origin the file came
 * from, the world is posted to it and forgotten: `sent`. Otherwise one word
 * says why not, and nothing that is kept is touched: a conversion still in
 * progress goes on exactly as it was.
 */
export async function handBackWorld(win: { opener: unknown }, kept: Kept, now: number): Promise<HandBack> {
  const opener = (win.opener ?? null) as Opener | null;
  const say = (word: Exclude<ImportSignal, 'waiting'>): typeof word => {
    try {
      // A word carries nothing, so it may go to whoever opened this window.
      opener?.postMessage(importSignal(word), '*');
    } catch {
      // Nobody to tell.
    }
    return word;
  };
  if (opener === null) return 'empty';
  const { store, scopeUrl } = kept;
  const raw = await store.get(noteUrl(scopeUrl));
  if (raw === null) return say('empty');
  const note = readHandbackNote(new TextDecoder().decode(raw), now);
  if (note === null) {
    // A finished world kept too long, or not a note this host wrote: nothing here is given to anyone.
    await store.clear?.();
    return say('empty');
  }
  const answer = handbackAnswer(note, now);
  if (answer !== 'ready' || note.origin === null) return say(answer === 'ready' ? 'empty' : answer);
  const opened = await takeOpenedWorld(store, scopeUrl);
  if (opened === null) return say('empty');
  const files: HandoffFile[] = [];
  for (const each of opened.files) {
    const bytes = await store.get(each.url);
    if (bytes === null) {
      await store.clear?.();
      return say('empty');
    }
    files.push({ path: each.path, bytes });
  }
  opener.postMessage(importHandoff(opened.title, files), note.origin);
  await store.clear?.();
  return 'sent';
}

const NO_FILE = 'No file was handed to this window. Go back to WebVerse and choose the file again.';
const NOT_KEPT = 'This browser could not keep the file for Blender here. Try again, or try another browser.';

/** Runs whichever of the two windows this page was opened as. A page that is neither does nothing. */
export function mountBlendWindow(doc: Document, deps: ImportDeps): void {
  const win = doc.defaultView;
  if (!win) return;
  const mode = blendWindowMode(win.location.href);
  if (mode === null) return;
  const style = doc.createElement('style');
  style.textContent = CONVERTER_WINDOW_CSS;
  doc.head.appendChild(style);
  const leave: StageAction = { label: 'Close this window', run: () => win.close() };
  const kept = async (): Promise<Kept> => {
    const { ensureImportServer } = await import('./importServer');
    const server = await ensureImportServer(win);
    return { store: server.store, scopeUrl: server.scopeUrl };
  };
  const clock: ProgressClock = {
    now: () => Date.now(),
    every: (ms, run) => {
      const timer = win.setInterval(run, ms);
      return () => win.clearInterval(timer);
    },
  };
  const nothing = (line: string): void => showStage(doc, 'failed', 'Nothing to convert', [line, 'You can close this window.'], [leave]);

  if (mode === 'take') {
    void kept()
      .then((place) => handBackWorld(win, place, Date.now()))
      .catch((): HandBack => {
        try {
          (win.opener as Opener | null)?.postMessage(importSignal('empty'), '*');
        } catch {
          // Nobody to tell.
        }
        return 'empty';
      })
      .then((outcome) => {
        win.close();
        // Shown only where the browser would not close the window.
        showStage(doc, outcome === 'sent' ? 'converted' : 'failed', outcome === 'sent' ? 'Opened in WebVerse' : 'Nothing is ready yet', ['You can close this window.'], [leave]);
      });
    return;
  }

  if (!isIsolationRequest(win.location.href)) {
    showStage(doc, 'converting', 'Blender', ['Getting your file from WebVerse.']);
    // The store first, so that the note can say this window is waiting before any file arrives, and so that a
    // browser that will keep nothing here is found out before the visitor's file is asked for.
    void kept().then(
      async (place) => {
        await writeNote(place, { origin: null, at: Date.now(), stage: 'waiting', beat: Date.now() }).catch(() => undefined);
        awaitBlendFile(
          win,
          async () => place,
          () => Date.now(),
          (outcome) => {
            if (outcome === 'kept') win.location.replace(isolatedUrl(win.location.href));
            else nothing(outcome === 'failed' ? NOT_KEPT : NO_FILE);
          },
        );
      },
      () => nothing(NOT_KEPT),
    );
    return;
  }

  // Isolated now, and cut off from the window that opened this one: the file is in the cache, with who it is for.
  void (async () => {
    const place = await kept();
    const note = await readNote(place, Date.now());
    const pending = await takePendingImport(place.store, place.scopeUrl);
    if (note === null || note.origin === null || pending === null) {
      if (note !== null && note.origin !== null) await writeNote(place, { origin: note.origin, at: note.at, stage: 'failed', beat: Date.now(), why: 'the kept file was not there after the window reloaded' }).catch(() => undefined);
      nothing(NO_FILE);
      return;
    }
    const progress = keepProgress(place, note.origin, note.at, clock);
    // Watched from before Blender is loaded, so a failure in loading it is caught too.
    watchForTrouble(win, (line) => progress.error(line));
    startWatchdog(win, place.scopeUrl, (line) => progress.error(line));
    progress.set('isolated');
    const { convertInWindow } = await import('./blendImport');
    const converted = await convertInWindow(
      doc,
      pending.model,
      pending.sidecars,
      deps,
      leave,
      (at) => progress.set(at.stage, at),
      (line) => progress.line(line),
    ).catch((err: unknown) => {
      progress.set('failed', { why: err instanceof Error ? err.message : String(err) });
      return false;
    });
    if (!converted) {
      // The card says why; so does the note, for whoever asks for the world.
      progress.set('failed', { why: 'the conversion ended without a world' });
      return;
    }
    // Staging the world emptied the store first: the note is written again, as ready, dated from now.
    progress.set('ready');
    await progress.settled();
    showStage(doc, 'converted', `${pending.model.name} is ready.`, ['Go back to WebVerse and press Open it.', 'You can close this window.'], [leave]);
  })().catch(() => nothing(NOT_KEPT));
}
